---
import PageLayout from "../../layouts/PageLayout.astro";
import { getTranslation } from "../../utils/i18n";

const lang = "en";
const t = getTranslation(lang);
---

<PageLayout
  title="Contact Aunova - Begin a Strategic Conversation"
  description="We welcome conversations with institutions building toward a long-term, human- and planet-positive future."
  lang={lang}
>
  <section class="contact-hero">
    <div class="container">
      <div class="hero-content">
        <h1>{t.contact.title}</h1>
        <p class="hero-intro">{t.contact.intro}</p>
      </div>
    </div>
  </section>

  <section class="contact-section">
    <div class="container">
      <div class="contact-grid">
        <div class="contact-form-wrapper">
          <form class="contact-form" action="https://formspree.io/f/xgokkved" method="POST">
            <div class="form-group">
              <label for="name">{t.contact.form.name}</label>
              <input type="text" id="name" name="name" required />
            </div>

            <div class="form-group">
              <label for="organization">{t.contact.form.organization}</label>
              <input type="text" id="organization" name="organization" required />
            </div>

            <div class="form-group">
              <label for="systemFamily">{t.contact.form.systemFamily}</label>
              <select id="systemFamily" name="systemFamily" required>
                <option value="">Select a system family...</option>
                {t.contact.form.systemFamilyOptions.map((option) => (
                  <option value={option}>{option}</option>
                ))}
              </select>
            </div>

            <div class="form-group">
              <label for="criticalSystem">{t.contact.form.criticalSystem}</label>
              <textarea id="criticalSystem" name="criticalSystem" rows="4" required></textarea>
            </div>

            <div class="form-group">
              <label>{t.contact.form.timeHorizon}</label>
              <div class="radio-group">
                {t.contact.form.timeHorizonOptions.map((option, index) => (
                  <label class="radio-label">
                    <input 
                      type="radio" 
                      name="timeHorizon" 
                      value={option} 
                      required={index === 0}
                    />
                    <span>{option}</span>
                  </label>
                ))}
              </div>
            </div>

            <button type="submit" class="btn btn-primary btn-lg">
              {t.contact.form.submit}
            </button>
          </form>

          <p class="form-closing">{t.contact.closing}</p>
        </div>

        <div class="contact-options">
          <div class="contact-card">
            <div class="card-content">
              <div class="contact-icon">
                <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                  <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
                  <line x1="16" y1="2" x2="16" y2="6"></line>
                  <line x1="8" y1="2" x2="8" y2="6"></line>
                  <line x1="3" y1="10" x2="21" y2="10"></line>
                </svg>
              </div>
              <h3>Schedule a Call</h3>
              <p>Book a 30-minute strategic conversation</p>
            </div>
            <a
              href="https://cal.com/ngmisl/aunova"
              target="_blank"
              rel="noopener"
              class="btn btn-outline"
            >
              Book Meeting
            </a>
          </div>

          <div class="contact-card">
            <div class="card-content">
