<style>
  .contact-hero {
    padding: var(--space-3xl) 0;
    background: linear-gradient(
      135deg,
      var(--color-background) 0%,
      color-mix(in srgb, var(--color-secondary) 10%, var(--color-background)) 100%
    );
  }

  .hero-content {
    text-align: center;
    max-width: 800px;
    margin: 0 auto;
  }

  .hero-content h1 {
    font-size: var(--text-4xl);
    font-weight: 700;
    color: var(--color-primary);
    margin-bottom: var(--space-lg);
  }

  .hero-intro {
    font-size: var(--text-lg);
    color: var(--color-text-muted);
    line-height: 1.7;
  }

  .contact-section {
    padding: var(--space-3xl) 0 var(--space-5xl);
  }

  .contact-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: var(--space-3xl);
    max-width: 1100px;
    margin: 0 auto;
  }

  .contact-form-wrapper {
    background: var(--color-background-elevated, var(--color-white));
    border: 1px solid var(--color-border);
    border-radius: var(--radius-xl);
    padding: var(--space-2xl);
  }

  .contact-form {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
  }

  .form-group {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
  }

  .form-group label {
    font-weight: 600;
    font-size: var(--text-sm);
    color: var(--color-text);
  }

  .form-group input,
  .form-group textarea,
  .form-group select {
    padding: var(--space-md);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-md);
    font-size: var(--text-base);
    background: var(--color-background);
    color: var(--color-text);
    transition: border-color var(--transition-fast);
  }

  .form-group input:focus,
  .form-group textarea:focus,
  .form-group select:focus {
    outline: none;
    border-color: var(--color-primary);
  }

  .radio-group {
    display: flex;
    gap: var(--space-xl);
  }

  .radio-label {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    cursor: pointer;
    font-weight: 400;
  }

  .radio-label input {
    width: 20px;
    height: 20px;
    accent-color: var(--color-primary);
  }

  .form-closing {
    margin-top: var(--space-lg);
    font-size: var(--text-sm);
    color: var(--color-text-muted);
    font-style: italic;
    text-align: center;
  }

  .contact-options {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
  }

  .contact-card {
    padding: var(--space-lg);
    background: var(--color-background-elevated, var(--color-white));
    border: 1px solid var(--color-border);
    border-radius: var(--radius-lg);
    transition: all var(--transition-base);
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  .contact-card:hover {
    border-color: var(--color-primary);
    box-shadow: var(--shadow-md);
  }

  .card-content {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
  }

  .contact-icon {
    display: inline-flex;
    justify-content: center;
    align-items: center;
    width: 48px;
    height: 48px;
    background: color-mix(in srgb, var(--color-primary) 10%, var(--color-background));
    border-radius: var(--radius-md);
    color: var(--color-primary);
  }

  .contact-card h3 {
    font-size: var(--text-lg);
    font-weight: 700;
    margin: 0;
    color: var(--color-text);
  }

  .contact-card p {
    font-size: var(--text-sm);
    color: var(--color-text-muted);
    margin: 0;
    line-height: 1.5;
  }

  .btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--space-sm) var(--space-xl);
    border-radius: var(--radius-md);
    font-weight: 600;
    font-size: var(--text-base);
    transition: all var(--transition-fast);
    text-decoration: none;
    cursor: pointer;
    border: 2px solid transparent;
  }

  .btn-lg {
    padding: var(--space-md) var(--space-2xl);
    width: 100%;
  }

  .btn-primary {
    background-color: var(--color-primary);
    color: var(--color-white);
    border-color: var(--color-primary);
  }

  .btn-primary:hover {
    background-color: var(--color-primary-hover);
    border-color: var(--color-primary-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
    text-decoration: none;
    color: var(--color-white);
  }

  .btn-outline {
    background-color: transparent;
    color: var(--color-primary);
    border-color: var(--color-primary);
    font-size: var(--text-sm);
    padding: var(--space-sm) var(--space-md);
  }

  .btn-outline:hover {
    background-color: var(--color-primary);
    color: var(--color-white);
    text-decoration: none;
  }

  @media (max-width: 1024px) {
    .contact-grid {
      grid-template-columns: 1fr;
      gap: var(--space-2xl);
    }

    .contact-options {
      flex-direction: row;
      flex-wrap: wrap;
    }

    .contact-card {
      flex: 1;
      min-width: 200px;
    }
  }

  @media (max-width: 768px) {
    .contact-hero {
      padding: var(--space-2xl) 0;
    }

    .hero-content h1 {
      font-size: var(--text-3xl);
    }

    .hero-intro {
      font-size: var(--text-base);
    }

    .contact-section {
      padding: var(--space-2xl) 0 var(--space-3xl);
    }

    .contact-grid {
      gap: var(--space-xl);
    }

    .contact-form-wrapper {
      padding: var(--space-lg);
      border-radius: var(--radius-lg);
    }

    .contact-options {
      flex-direction: column;
    }

    .contact-card {
      min-width: unset;
    }

    .radio-group {
      flex-direction: column;
      gap: var(--space-md);
    }

    .btn-outline {
      padding: var(--space-md) var(--space-lg);
      min-height: 44px;
    }
  }

  @media (max-width: 480px) {
    .contact-hero {
      padding: var(--space-xl) 0;
    }

    .hero-content h1 {
      font-size: var(--text-2xl);
    }

    .contact-section {
      padding: var(--space-xl) 0 var(--space-2xl);
    }

    .contact-form-wrapper {
      padding: var(--space-md);
    }

    .contact-form {
      gap: var(--space-md);
    }

    .btn-lg {
      padding: var(--space-md) var(--space-lg);
    }
  }
</style>

